for(const button of document.querySelectorAll('[data-campus-level]'))button.onclick=()=>{campusCount=Number(button.dataset.campusLevel);if(campusFloor!=='all'&&Number(campusFloor)>=campusCount)campusFloor='all';const style=project.design.interiorStyle;project=DesignCampus.project(studyId,project.size,project.depth,campusCount);if(style)project.design.interiorStyle=style;parts=WorkshopDesign.envelope(project);$('pieceCount').textContent=parts.length+' pièces architecturales natives';syncCampusButtons();syncDownload();rebuild();};
for(const button of document.querySelectorAll('[data-campus-cut]'))button.onclick=()=>{campusFloor=button.dataset.campusCut;mode=campusFloor==='all'?'exterior':'interior';$('viewLabel').textContent=mode==='interior'?'COUPE / NIVEAU '+(Number(campusFloor)+1):'COMPOSITION / ENSEMBLE';for(const b of document.querySelectorAll('[data-view]'))b.setAttribute('aria-pressed',String(b.dataset.view===mode));yaw=3.8;pitch=mode==='interior'?.62:.43;zoom=mode==='interior'?1.4:1.2;$('zoom').value=zoom;syncCampusButtons();rebuild();};

fetch('/atlas-scene.json').then(r=>{if(!r.ok)throw new Error('La maquette est indisponible.');return r.json();}).then(p=>{project=studySpec.designFirst?DesignCampus.project(studyId):p;project.design.family=Object.keys(ArchitectureCatalog.families).find(k=>ArchitectureCatalog.families[k].nativeStudy===studyId);project.design.nativeStudy=studyId;project.id=studyId+'-study';project.name=studySpec.title;document.title=project.name;$('study').setAttribute('aria-label','Maquette 3D de '+studySpec.title+'. Glisser pour tourner ; molette pour zoomer.');const index=Object.keys(ArchitectureCatalog.studies).indexOf(studyId)+1;document.querySelector('.study-index').textContent='ARCHITECTURES COMPOSÉES / '+String(index).padStart(2,'0');const heading=document.querySelector('h1');heading.textContent=studySpec.displayName||({atlas:'Atlas',lumen:'Lumen'}[studyId])||studySpec.title;const sub=document.createElement('span');sub.textContent='Étude '+String(index).padStart(2,'0');heading.append(sub);heading.classList.toggle('long-title',(studySpec.displayName||studyId).length>8);document.querySelector('.eyebrow').textContent=(studySpec.subtitle||({atlas:'Une halle, quatre échelles',lumen:'Coque claire / horizon panoramique'}[studyId])||studySpec.category).toUpperCase();document.querySelector('.intro').textContent=studySpec.description;const labels=studySpec.principles||(studyId==='lumen'?[['Une coque continue','Pans coupés et larges rubans clairs plutôt qu’une charpente apparente.'],['Un horizon vitré','Vitrage horizontal intégré entre les pleins de la coque.'],['Une entrée asymétrique','Pavillon bas, porche en retrait et seuil dégagé vers la production.'],['Des services intégrés','Annexe basse fermée ; accents cyan peints, sans émission lumineuse.']]:null);if(labels)document.querySelectorAll('.principles li').forEach((li,i)=>{li.querySelector('strong').textContent=labels[i][0];li.querySelector('p').textContent=labels[i][1];});const valid=(value,min,max)=>{const n=Number(value);return Number.isInteger(n)&&n>=min&&n<=max&&(n-min)%8===0?n:min;};project.size=valid(params.get('width'),studySpec.resize.width.min,studySpec.resize.width.max);project.depth=valid(params.get('length'),studySpec.resize.length.min,studySpec.resize.length.max);if(studySpec.grammar){const w=studySpec.resize.width,d=studySpec.resize.length;if((project.size-w.min)%w.step)project.size=w.min;if((project.depth-d.min)%d.step)project.depth=d.min;project=DesignCampus.project(studyId,project.size,project.depth,campusCount);}project.design.studyHeightMode=$('studyCompact').checked?'auto':'reference';if($('studyLiving').checked&&!studySpec.designFirst){try{project=CreationLiving.plan(project);}catch{delete project.design.living;}}parts=WorkshopDesign.envelope(project);syncDownload();syncDimensions();syncCampusButtons();$('pieceCount').textContent=parts.length+' pièces architecturales natives';$('sceneStatus').textContent=studySpec.designFirst?'Architecture et décoration · emplacements libres · machines et convoyeurs non inclus':'60 minerais de cuivre → 60 lingots/min théoriques · réseau exporté : '+p.studyProof.belts+' convoyeurs, '+p.studyProof.lifts+' élévateurs';if(studySpec.designFirst){$('studyCompact').parentElement.hidden=true;zoom=studySpec.sourceArchitecture?1:studySpec.campus?1.2:1.15;$('zoom').value=zoom;document.querySelector('.download').nextElementSibling.textContent=studySpec.campus?'Architecture seule · 64 ou 96 m de largeur · 48 / 64 / 80 m de longueur · 1 à 3 niveaux. Aucun layout existant n’est imposé.':studySpec.grammar?'Architecture et décoration · 64 / 80 / 96 m de largeur · 48 / 64 / 80 m de longueur.':'Architecture seule · largeur 64 à 96 m et longueur 48 à 80 m par travées de 8 m.';document.querySelector('.drawing-note span:last-child').textContent='ARCHITECTURE SEULE · RÉSERVES LOGISTIQUES';}if(studySpec.grammar){if(studySpec.campus){$('campusControl').hidden=false;$('campusCutControl').hidden=false;}for(const picker of document.querySelectorAll('.dimension-picker')){const v=picker.dataset.dimension==='width'?studySpec.resize.width:studySpec.resize.length;for(const b of picker.querySelectorAll('[data-size]'))b.disabled=(Number(b.dataset.size)-v.min)%v.step!==0;}}if(studySpec.creationKind==='interior'){mode='interior';pitch=.62;zoom=1.3;$('zoom').value=zoom;$('viewLabel').textContent='INTÉRIEUR / UN NIVEAU DE PRODUCTION';for(const b of document.querySelectorAll('[data-view]'))b.setAttribute('aria-pressed',String(b.dataset.view==='interior'));}
if(studySpec.interiorStyles){$('interiorStyleControl').hidden=false;for(const b of document.querySelectorAll('[data-interior-style]')){b.setAttribute('aria-pressed',String(b.dataset.interiorStyle===project.design.interiorStyle));b.onclick=()=>{project.design.interiorStyle=b.dataset.interiorStyle;parts=WorkshopDesign.envelope(project);for(const q of document.querySelectorAll('[data-interior-style]'))q.setAttribute('aria-pressed',String(q===b));syncDownload();rebuild();};}}
if(studySpec.ledColor){const initial=params.get('led');project.design.ledColor=/^[0-9a-f]{6}$/i.test(initial||'')?'#'+initial:studySpec.ledColor;const updateLED=color=>{project.design.ledColor=color;$('ledColor').value=color;parts=WorkshopDesign.envelope(project);syncDownload();const url=new URL(location.href);url.searchParams.set('led',color.slice(1));history.replaceState(null,'',url);for(const b of document.querySelectorAll('[data-led-color]'))b.setAttribute('aria-pressed',String(b.dataset.ledColor===color));rebuild();};$('ledControl').hidden=false;$('ledColor').oninput=()=>updateLED($('ledColor').value);for(const b of document.querySelectorAll('[data-led-color]'))b.onclick=()=>updateLED(b.dataset.ledColor);updateLED(project.design.ledColor);}
if(studySpec.sourceArchitecture){document.querySelector('.download').nextElementSibling.textContent='Architecture Copper · 104–136 m × 88–120 m · travées de 8 m · sans machines ni réseaux de production.';const ul=document.querySelector('.sources ul');ul.replaceChildren();const li=document.createElement('li');li.textContent=studySpec.reference;ul.append(li);}
if(studySpec.squareModule){$('studyLiving').parentElement.hidden=true;document.querySelector('.dimension-controls').style.display='none';document.querySelector('.study-index').textContent='COMPACT / ÉTUDE DU MODULE CARRÉ';document.querySelector('[data-view=front]').textContent='Angle signature';document.querySelector('.download').nextElementSibling.textContent='Module de référence 48 × 48 m · étude extérieure en cours · extensions à travailler après cette base.';document.querySelector('.sources ul').innerHTML='<li><a href="https://www.youtube.com/watch?v=Js7zbvNY7CM&amp;t=190s" target="_blank" rel="noopener">Compact Factory · Reekitect · référence unique</a></li>';yaw=3.926990817;pitch=.35;zoom=1.35;$('zoom').value=zoom;}
syncCampusButtons();rebuild();}).catch(e=>{$('error').hidden=false;$('error').textContent=e.message;});
